    "when": "Проверьте здесь, соответствует ли каждая песня нужному жанру.",
    "click": "Здесь отображается только информация. Чтобы изменить жанр, нажмите [[Редактировать]] в этой строке.",
    "care": "Основной жанр определяет, в какую категорию будет отнесена песня на aimusiclist.com. Дополнительные жанры отображаются рядом с названием. На экране телефона эта колонка скрыта.",
