    "click": "[[Предпросмотр]] воспроизводит песню здесь (нажмите [[Остановить]], чтобы остановить). [[Редактировать]] открывает форму для выбора песни в верхней части страницы. [[Удалить]] запрашивает подтверждение, после чего немедленно удаляет песню и её аудиофайл.",
    "care": "Удаление необратимо. Песня также исчезает с aimusiclist.com. [[Предпросмотр]] отображается только для песен с аудиофайлом. Песню в общедоступном альбоме нельзя удалить, если количество песен в альбоме уменьшится до менее чем 6.",
