    "when": "Оставьте галочку напротив песен, которые вы хотите, чтобы услышал весь мир и чтобы у них был шанс попасть в Топ-100. Снимите галочку, если хотите, чтобы песни были только на вашем сайте.",
    "click": "Сохранение происходит при загрузке или нажатии кнопки [[Сохранить трек]]. Опубликованные песни появляются на aimusiclist.com через несколько минут. Вы можете изменить это позже в списке песен.",
    "care": "По меньшей мере 10 песен должны оставаться общедоступными (все песни, если их меньше 10). Таким образом, новую песню можно опубликовать, даже если флажок не отмечен, а сохранение песни без флажка может быть отклонено. Для песни в общедоступном альбоме этот флажок остается отмеченным, и снятие флажка ничего не меняет, пока альбом не станет приватным.",
