    "care": "В списке может быть до 20 файлов. Лишние файлы исключаются. Размер файлов MP3 и M4A не должен превышать 15 МБ. Файл WAV преобразуется в MP3 с битрейтом 320 кбит/с, и этот MP3-файл также не должен превышать 15 МБ (примерно 6,5 минут). Длительность каждой песни должна составлять от 30 секунд до 15 минут.",
