    "what": "На этой вкладке отображается количество посетителей вашего сайта и количество прослушанных ими песен. Здесь же вы можете увидеть свои данные с aimusiclist.com.",
    "when": "Открывайте его раз в день или раз в неделю. Вы сможете увидеть, какие песни нравятся людям и растет ли ваш сайт.",
    "click": "При просмотре сайта ничего не меняется. Выберите точку вверху, и каждая карточка ниже будет отображать эту точку.",
    "care": "Большинство записей подсчитываются **раз в день** (рано утром по UTC). Песня, которую вы загрузили сегодня, отобразится в статистике за завтрашний день.",
    "like": "Это как блокнот владельца магазина. Каждое утро вы записываете, сколько посетителей зашло и какие песни они слушали."
