    "when": "Добавьте его один раз. Этот же ключ также отображает вашу комнату в бесплатном тарифном плане в верхней части экрана администратора.",
    "click": "Перейдите на вкладку **Информация о сайте** и вставьте туда ключ. Для использования ключа необходимы права доступа, указанные в сообщении. Ваши данные отобразятся начиная со следующего ежедневного подсчета.",
